// crypto_pki's certificates, made once with OpenSSL 3.0.13 by the script
// below and checked in as DER in hex. Every one is valid from 2026-01-01 to
// 2027-01-01 (START_MS to END_MS) unless its dates say otherwise, and the
// tests judge them at NOW_MS, 2026-06-01T00:00:00Z. `openssl verify -attime
// 1780272000 -purpose sslserver -CAfile root.pem -untrusted int.pem leaf.pem`
// printed OK, and so did the same with int_nc_ok.pem, int_server.pem,
// int_nc_exok.pem or int_nc_wildperm_ok.pem for int.pem, and with
// int_roll.pem beside int.pem for leaf_roll.pem, and under rroot.pem with
// rint.pem or rint_pss.pem for leaf_rsa.pem.
//
//   #!/bin/bash
//   # Makes crypto_pki's fixtures with OpenSSL 3.0.13 in the current directory.
//   set -euo pipefail
//   START=20260101000000Z; END=20270101000000Z
//   key() { case "$2" in p256) openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-256 -out "$1.key" 2>/dev/null;;
//     p384) openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-384 -out "$1.key" 2>/dev/null;;
//     ed) openssl genpkey -algorithm ed25519 -out "$1.key";; rsa*) openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:${2#rsa} -out "$1.key" 2>/dev/null;; esac; }
