//     openssl req -new -key "$k.key" -subj "$subj" -out req.csr
//     local ser; ser=$(openssl rand -hex 8); echo "$ser" > db/serial
//     if [ "$icert" = self ]; then
//       openssl ca -batch -config ca.cnf -selfsign -keyfile "$k.key" -md "$md" ${SIGOPTS:-} -extensions x -startdate "$s" -enddate "$e" -in req.csr -out "$name.pem" -notext 2>/dev/null
//     else
//       openssl ca -batch -config ca.cnf -cert "$icert.pem" -keyfile "$ikey.key" -md "$md" ${SIGOPTS:-} -extensions x -startdate "$s" -enddate "$e" -in req.csr -out "$name.pem" -notext 2>/dev/null
//     fi
//     openssl x509 -in "$name.pem" -outform DER -out "$name.der"
//   }
//   CA='basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign,cRLSign\nsubjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid'
//   LEAFX='basicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature\nextendedKeyUsage=serverAuth\nsubjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid'
//   SAN='subjectAltName=DNS:example.com,DNS:*.example.org,IP:192.0.2.1,IP:2001:db8::1'
//   key root p384; key int p384; key leaf p256; key other p256; key sub p256; key wrong p384
//   sign root "/CN=nish-pki-root" root self root sha384 "$CA"
//   sign other "/CN=nish-pki-other" other self other sha256 "$CA"
//   sign int "/CN=nish-pki-int" int root root sha384 "$CA"
//   sign leaf "/CN=example.com" leaf int int sha384 "$LEAFX\n$SAN"
//   # the intermediate's variants: the same Name and key, other extensions or dates
//   sign int_expired "/CN=nish-pki-int" int root root sha384 "$CA" 20250101000000Z 20260301000000Z
//   sign int_future "/CN=nish-pki-int" int root root sha384 "$CA" 20260901000000Z 20270101000000Z
//   sign int_noca "/CN=nish-pki-int" int root root sha384 'basicConstraints=critical,CA:FALSE\nkeyUsage=critical,keyCertSign\nsubjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid'
//   sign int_nobc "/CN=nish-pki-int" int root root sha384 'keyUsage=critical,keyCertSign\nsubjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid'
//   sign int_nokcs "/CN=nish-pki-int" int root root sha384 'basicConstraints=critical,CA:TRUE\nkeyUsage=critical,digitalSignature,cRLSign\nsubjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid'
//   sign int_client "/CN=nish-pki-int" int root root sha384 "$CA\nextendedKeyUsage=clientAuth"
//   sign int_anyeku "/CN=nish-pki-int" int root root sha384 "$CA\nextendedKeyUsage=anyExtendedKeyUsage"
//   sign int_critical "/CN=nish-pki-int" int root root sha384 "$CA\n1.3.6.1.4.1.55555.1=critical,DER:0500"
//   sign int_pathlen0 "/CN=nish-pki-int" int root root sha384 "$CA\nbasicConstraints=critical,CA:TRUE,pathlen:0"
//   sign int_nc_ok "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;DNS:example.com,permitted;DNS:.example.org,permitted;IP:192.0.2.0/255.255.255.0,permitted;IP:2001:db8::/ffff:ffff::,permitted;dirName:dir_ok\n[dir_ok]\nCN=example.com"
//   sign int_nc_excluded "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,excluded;DNS:example.com"
//   sign int_nc_permitted "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;DNS:other.test"
//   sign int_nc_ip "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;DNS:example.com,permitted;DNS:example.org,permitted;IP:198.51.100.0/255.255.255.0"
//   sign int_nc_email "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;email:example.com"
//   sign int_nc_dir "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,excluded;dirName:dir_x\n[dir_x]\nCN=nish-elsewhere"
//   sign int_sha1 "/CN=nish-pki-int" int root root sha1 "$CA"
//   sign int_nc_dirperm "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;DNS:example.com,permitted;DNS:.example.org,permitted;dirName:dir_e\n[dir_e]\nCN=nish-elsewhere"
//   sign int_nc_ipexcl "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,excluded;IP:192.0.2.0/255.255.255.0"
//   sign int_server "/CN=nish-pki-int" int root root sha384 "$CA\nextendedKeyUsage=serverAuth"
//   sign int_nc_exok "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,excluded;DNS:example.net,excluded;DNS:www.example.net,excluded;IP:198.51.100.0/255.255.255.0,excluded;IP:2001:db9::/ffff:ffff::"
//   # a wildcard SAN against a subtree below its base, excluded and permitted, a permitted twin at the base, and an excluded subtree above it
//   sign int_nc_wildex "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,excluded;DNS:www.example.org"
//   sign int_nc_wildup "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,excluded;DNS:org"
//   sign int_nc_wildperm "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;DNS:example.com,permitted;DNS:www.example.org"
//   sign int_nc_wildperm_ok "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;DNS:example.com,permitted;DNS:example.org"
//   # a dNSName subtree of ".", which covers every name
//   sign int_nc_dotperm "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;DNS:."
//   sign int_nc_dotexcl "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,excluded;DNS:."
//   # a different key under the intermediate's Name, without a key identifier to tell it apart
//   sign int_wrong "/CN=nish-pki-int" wrong root root sha384 'basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign\nsubjectKeyIdentifier=none\nauthorityKeyIdentifier=keyid'
//   # leaves under the intermediate
//   sign leaf_anyeku "/CN=example.com" leaf int int sha384 "basicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature\nextendedKeyUsage=anyExtendedKeyUsage\nsubjectKeyIdentifier=hash\nauthorityKeyIdentifier=keyid\n$SAN"
//   # a leaf whose subject is its issuer's, so self-issued
//   sign leaf_selfiss "/CN=nish-pki-int" leaf int int sha384 "$LEAFX\n$SAN"
//   sign leaf_cn "/CN=example.com" leaf int int sha384 "$LEAFX"
//   sign leaf_ca "/CN=example.com" leaf int int sha384 "basicConstraints=critical,CA:TRUE\nkeyUsage=critical,digitalSignature,keyCertSign\nauthorityKeyIdentifier=keyid\n$SAN"
//   sign leaf_ku "/CN=example.com" leaf int int sha384 "basicConstraints=critical,CA:FALSE\nkeyUsage=critical,keyEncipherment\nauthorityKeyIdentifier=keyid\n$SAN"
//   sign leaf_client "/CN=example.com" leaf int int sha384 "basicConstraints=critical,CA:FALSE\nextendedKeyUsage=clientAuth\nauthorityKeyIdentifier=keyid\n$SAN"
//   sign leaf_critical "/CN=example.com" leaf int int sha384 "$LEAFX\n$SAN\n1.3.6.1.4.1.55555.1=critical,DER:0500"
//   sign leaf_expired "/CN=example.com" leaf int int sha384 "$LEAFX\n$SAN" 20250101000000Z 20260301000000Z
//   sign leaf_future "/CN=example.com" leaf int int sha384 "$LEAFX\n$SAN" 20260901000000Z 20270101000000Z
//   # a second intermediate, for pathLenConstraint
//   sign sub "/CN=nish-pki-sub" sub int int sha384 "$CA"
//   sign leaf_sub "/CN=example.com" leaf sub sub sha256 "$LEAFX\n$SAN"
//   # a cross-signed loop: A is issued by B and B by A, and neither by a root
//   key loopa p256; key loopb p256
//   sign loopa0 "/CN=nish-pki-loop-a" loopa self loopa sha256 "$CA"
//   sign loopb0 "/CN=nish-pki-loop-b" loopb self loopb sha256 "$CA"
//   sign loopa "/CN=nish-pki-loop-a" loopa loopb0 loopb sha256 "$CA"
//   sign loopb "/CN=nish-pki-loop-b" loopb loopa0 loopa sha256 "$CA"
//   sign leaf_loop "/CN=example.com" leaf loopa0 loopa sha256 "$LEAFX\n$SAN"
//   # one self-issued CA without key identifiers; the test copies it a hundred times
//   key same p256
//   sign same "/CN=nish-pki-same" same self same sha256 'basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign\nsubjectKeyIdentifier=none\nauthorityKeyIdentifier=none'
//   sign leaf_same "/CN=example.com" leaf same same sha256 "basicConstraints=critical,CA:FALSE\nauthorityKeyIdentifier=none\n$SAN"
//   # nine certificates deep: root, chain1 .. chain7 and a leaf; and eight deep
//   prev=root; pkey=root
//   for i in 1 2 3 4 5 6 7; do key chain$i p256; sign chain$i "/CN=nish-pki-chain$i" chain$i $prev $pkey sha256 "$CA"; prev=chain$i; pkey=chain$i; done
//   sign leaf_deep "/CN=example.com" leaf chain7 chain7 sha256 "$LEAFX\n$SAN"
//   sign leaf_deep8 "/CN=example.com" leaf chain6 chain6 sha256 "$LEAFX\n$SAN"
//   # the per-certificate bounds: 1024 and 1025 names, 256 and 257 subtrees
//   names() { local s="DNS:example.com"; for i in $(seq 2 $1); do s="$s,DNS:n$i.example.com"; done; echo "$s"; }
//   trees() { local s="permitted;DNS:example.com,permitted;DNS:example.org"; for i in $(seq 3 $1); do s="$s,permitted;DNS:t$i.example.com"; done; echo "$s"; }
//   sign leaf_1024 "/CN=example.com" leaf int int sha384 "$LEAFX\nsubjectAltName=$(names 1024)"
//   sign leaf_1025 "/CN=example.com" leaf int int sha384 "$LEAFX\nsubjectAltName=$(names 1025)"
//   sign int_256 "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,$(trees 256)"
//   sign int_257 "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,$(trees 257)"
//   # Ed25519: a root and a leaf under it
//   key edroot ed
//   sign edroot "/CN=nish-pki-ed-root" edroot self edroot null "$CA"
//   sign leaf_ed "/CN=example.com" leaf edroot edroot null "$LEAFX\n$SAN"
//   # a key rollover: a new key under the intermediate's Name, issued by the old one, so self-issued; only it signs leaf_roll
//   key roll p384
//   sign int_roll "/CN=nish-pki-int" roll int int sha384 "$CA"
//   sign leaf_roll "/CN=example.com" leaf int_roll roll sha384 "$LEAFX\n$SAN"
//   # IPv6 subtrees only, one of them c000:201::/32, whose first four octets are 192.0.2.1's
//   sign int_nc_ip6 "/CN=nish-pki-int" int root root sha384 "$CA\nnameConstraints=critical,permitted;DNS:example.com,permitted;DNS:.example.org,permitted;IP:c000:201::/ffff:ffff::,permitted;IP:2001:db8::/ffff:ffff::"
//   # the intermediate's key identifier on a key that is not the intermediate's
//   sign int_wrongid "/CN=nish-pki-int" wrong root root sha384 "$CA"
//   # a root's Name on a CA:FALSE certificate of the root's key
//   sign root_noca "/CN=nish-pki-root" root self root sha384 'basicConstraints=critical,CA:FALSE\nkeyUsage=critical,keyCertSign\nsubjectKeyIdentifier=hash'
//   # a Name on a key of the other family, without a key identifier: an Ed25519 key named as the intermediate, a P-256 key as the Ed25519 root
//   sign int_edkey "/CN=nish-pki-int" edroot self edroot null 'basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign\nsubjectKeyIdentifier=none'
//   sign edroot_p256 "/CN=nish-pki-ed-root" other self other sha256 'basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign\nsubjectKeyIdentifier=none'
//   # empty Names: a root without one and a leaf it issues, and a leaf without a subject under the intermediate
//   key empty p256
//   sign root_empty "/" empty self empty sha256 'basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign\nsubjectKeyIdentifier=none'
//   sign leaf_emptyiss "/CN=example.com" leaf root_empty empty sha256 "basicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature\n$SAN"
//   sign leaf_nosubj "/" leaf int int sha384 "$LEAFX\nsubjectAltName=critical,DNS:example.com"
//   # a name that only ends in example.com
//   sign leaf_suffix "/CN=example.com" leaf int int sha384 "$LEAFX\nsubjectAltName=DNS:example.com,DNS:badexample.com"
//   # RSA: a 2048-bit root, intermediate and leaf, the intermediate also signed with PSS and the leaf with each hash; a 1024-bit root and a leaf under it
//   key rroot rsa2048; key rint rsa2048; key rleaf rsa2048; key rweak rsa1024
//   sign rroot "/CN=nish-pki-rsa-root" rroot self rroot sha256 "$CA"
//   sign rint "/CN=nish-pki-rsa-int" rint rroot rroot sha256 "$CA"
//   SIGOPTS="-sigopt rsa_padding_mode:pss -sigopt rsa_pss_saltlen:32" sign rint_pss "/CN=nish-pki-rsa-int" rint rroot rroot sha256 "$CA"
//   sign leaf_rsa "/CN=example.com" rleaf rint rint sha256 "$LEAFX\n$SAN"
//   sign leaf_rsa384 "/CN=example.com" rleaf rint rint sha384 "$LEAFX\n$SAN"
//   sign leaf_rsa512 "/CN=example.com" rleaf rint rint sha512 "$LEAFX\n$SAN"
//   sign rweak "/CN=nish-pki-rsa-weak" rweak self rweak sha256 "$CA"
//   sign leaf_rweak "/CN=example.com" rleaf rweak rweak sha256 "$LEAFX\n$SAN"
//   # the RSA intermediate's Name on a P-256 key, without a key identifier
//   sign rint_ec "/CN=nish-pki-rsa-int" other self other sha256 'basicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign\nsubjectKeyIdentifier=none'
//   # a leaf whose RSA key rsaParsePublicKey refuses, 512 bits, under a P-256 root of its own
//   key sroot p256; key rshort rsa512
//   sign sroot "/CN=nish-pki-short-root" sroot self sroot sha256 "$CA"
//   sign leaf_rshort "/CN=example.com" rshort sroot sroot sha256 "$LEAFX\n$SAN"
//   rm -rf db ca.cnf req.csr
//

